ALTER POLICY driver_documents_select ON public.driver_documents USING (has_org_role(organization_id, ARRAY['SUPER_ADMIN','ORGANIZATION_ADMIN','BRANCH_MANAGER','FLEET_MANAGER','DRIVER_MANAGER']) OR EXISTS (SELECT 1 FROM public.drivers d WHERE d.id = driver_documents.driver_id AND d.vehicle_id IS NOT NULL AND user_can_access_asset(driver_documents.organization_id, NULL::uuid, d.vehicle_id)))